	9810: {
		names: [{ nominative: "Thursday of the Sixth Week of Lent", short: "Thursday of the Sixth Week of Lent" }],
		biographies: [],
		info: [],
		refs: [],
		services: [
			{
				hymns: [],
				sections: [
					{
						section: "sexte",
						items: [
							{
								kind: "troparion",
								text: "Forget not the voice of Thy servants, O Lord; remember that at all times we have placed our hope in Thee, O Allpowerful One, and help us, we pray.",
								type: "1",
								tone: "1",
								header: "Troparion of the Prophecy in the 1<sup>st</sup> Tone",
							},
							{
								kind: "prokeimenon",
								text: "This is the gate of the Lord,",
								type: "1a",
								tone: "4",
								header: "First Prokeimenon of the Prophecy in the 4<sup>th</sup> Tone",
							},
							{ kind: "prokeimenon", text: "the righteous shall enter in thereat.", type: "1b" },
							{
								kind: "stichos",
								text: "O give thanks unto the Lord, for He is good, for His mercy endureth for ever.",
								type: "1",
							},
							{
								kind: "prokeimenon",
								text: "The way of Thy commandments have I run,",
								type: "2a",
								tone: "4",
								header: "Second Prokeimenon of the Prophecy in the 4<sup>th</sup> Tone",
							},
							{ kind: "prokeimenon", text: "when Thou didst enlarge my heart.", type: "2b" },
							{ kind: "stichos", text: "Set before me for a law, O Lord, the way of Thy statutes.", type: "2" },
						],
					},
				],
			},
		],
		hymns: [],
	},
	9811: {
		names: [{ nominative: "Wednesday of the Sixth Week of Lent", short: "Wednesday of the Sixth Week of Lent" }],
		biographies: [],
		info: [],
		refs: [],
		services: [
			{
				hymns: [],
				sections: [
					{
						section: "sexte",
						items: [
							{
								kind: "troparion",
								text: "Deal with us according to Thy mercy, O Lord, and deliver us not up with our sins, O holy Master Almighty, we pray Thee.",
								type: "1",
								tone: "5",
								header: "Troparion of the Prophecy in the 5<sup>th</sup> Tone",
							},
							{
								kind: "prokeimenon",
								text: "O Lord, save your people, and bless Your inheritance",
								type: "1a",
								tone: "4",
								header: "First Prokeimenon of the Prophecy in the 4<sup>th</sup> Tone",
							},
							{
								kind: "prokeimenon",
								text: "<p>Praise the Lord, O ye servants, praise ye the name of the Lord.</p>",
								type: "1b",
							},
							{ kind: "stichos", text: "Blessed be the name of the Lord from henceforth and for evermore.", type: "1" },
							{
								kind: "prokeimenon",
								text: "Ye are blessed of the Lord,",
								type: "2a",
								tone: "6",
								header: "Second Prokeimenon of the Prophecy in the 6<sup>th</sup> Tone",
							},
							{ kind: "prokeimenon", text: "Who made heaven and the earth.", type: "2b" },
							{
								kind: "stichos",
								text: "The heaven of heaven belongeth to the Lord, but the earth He gave unto the sons of men.",
								type: "2",
							},
						],
					},
				],
			},
		],
		hymns: [],
	},
	9812: {
		names: [{ nominative: "Tuesday of the Sixth Week of Lent", short: "Tuesday of the Sixth Week of Lent" }],
		biographies: [],
		info: [],
		refs: [],
		services: [
			{
				hymns: [],
				sections: [
					{
						section: "sexte",
						items: [
							{
								kind: "troparion",
								text: "An invincible wall hast Thou given to our city, the Virgin who bore Thee; through her, O Savior, do Thou rescue our souls from the evils that surround us, we pray.",
								type: "1",
								tone: "5",
								header: "Troparion of the Prophecy in the 5<sup>th</sup> Tone",
							},
							{
								kind: "prokeimenon",
								text: "Help me, O Lord my God",
								type: "1a",
								tone: "4",
								header: "First Prokeimenon of the Prophecy in the 4<sup>th</sup> Tone",
							},
							{ kind: "prokeimenon", text: "<p>and save me according to Thy mercy.</p>", type: "1b" },
							{ kind: "stichos", text: "O God, my praise do not pass over in silence.", type: "1" },
							{
								kind: "prokeimenon",
								text: "Thou art a priest for ever,",
								type: "2a",
								tone: "4",
								header: "Second Prokeimenon of the Prophecy in the 4<sup>th</sup> Tone",
							},
							{ kind: "prokeimenon", text: "after the order of Melchisedek.", type: "2b" },
							{ kind: "stichos", text: "The Lord said unto my Lord: Set Thou at my right hand.", type: "2" },
						],
					},
				],
			},
		],
		hymns: [],
	},
	9813: {
		names: [{ nominative: "Monday of the Sixth Week of Lent", short: "Monday of the Sixth Week of Lent" }],
		biographies: [],
		info: [],
		refs: [],
		services: [
			{
				hymns: [],
				sections: [
					{
						section: "sexte",
						items: [
							{
								kind: "troparion",
								text: "This is the terrible day, O God, the evening of which we did not hope to attain; but in Thy love for mankind Thou hast vouchsafed us to behold it, O rice-Holy One, glory to Thee.",
								type: "1",
								tone: "6",
								header: "Troparion of the Prophecy in the 6<sup>th</sup> Tone",
							},
							{
								kind: "prokeimenon",
								text: "Let the heart of them be glad that seek the Lord.",
								type: "1a",
								tone: "6",
								header: "First Prokeimenon of the Prophecy in the 6<sup>th</sup> Tone",
							},
							{ kind: "prokeimenon", text: "Let the heart of them be glad that seek the Lord.", type: "1b" },
							{ kind: "stichos", text: "O give thanks unto the Lord and call upon His name.", type: "1" },
							{
								kind: "prokeimenon",
								text: "Blessed is the Lord God of Israel,",
								type: "2a",
								tone: "6",
								header: "Second Prokeimenon of the Prophecy in the 6<sup>th</sup> Tone",
							},
							{ kind: "prokeimenon", text: "from everlasting to everlasting.", type: "2b" },
							{
								kind: "stichos",
								text: "O give thanks unto the Lord, for He is good, for His mercy endureth for ever.",
								type: "2",
							},
						],
					},
				],
			},
		],
		hymns: [],
	},
