	9816: {
		names: [{ nominative: "Friday of the Fifth Week of Lent", short: "Friday of the Fifth Week of Lent" }],
		biographies: [],
		info: [],
		refs: [],
		services: [
			{
				hymns: [],
				sections: [
					{
						section: "sexte",
						items: [
							{
								kind: "troparion",
								text: "Supremely praised art Thou, O Christ our God, Who shakest the earth, to convert and to save them that dwell therein, and yet establishest it in Thy goodness and ineffable compassion; through the intercessions of the Theotokos, have mercy on us.",
								type: "1",
								tone: "0",
								header: "Troparion of the Prophecy in the 8<sup>th</sup> Tone",
							},
							{
								kind: "prokeimenon",
								text: "Of mercy and judgement will I sing unto Thee, O Lord.",
								type: "1a",
								tone: "4",
								header: "First Prokeimenon of the Prophecy in the 4<sup>th</sup> Tone",
							},
							{ kind: "prokeimenon", text: "Of mercy and judgement will I sing unto Thee, O Lord.", type: "1b" },
							{ kind: "stichos", text: "I will chant and have understanding in a blameless path.", type: "1" },
							{
								kind: "prokeimenon",
								text: "O Lord, hear my prayer",
								type: "2a",
								tone: "4",
								header: "Second Prokeimenon of the Prophecy in the 4<sup>th</sup> Tone",
							},
							{ kind: "prokeimenon", text: "<p>and let my cry come unto Thee.</p>", type: "2b" },
							{ kind: "stichos", text: "Turn not Thy face from me.", type: "2" },
						],
					},
				],
			},
		],
		hymns: [],
	},
	9817: {
		names: [
			{ nominative: "Thursday of the Great Canon of St Andrew", short: "Thursday of the Great Canon of St Andrew" },
		],
		biographies: [],
		info: [],
		refs: [],
		services: [
			{
				hymns: [],
				sections: [
					{
						section: "sexte",
						items: [
							{
								kind: "troparion",
								text: "O compassionate, long-suffering, almighty Lord, send down Thy mercy on Thy people.",
								type: "1",
								tone: "6",
								header: "Troparion of the Prophecy in the 6<sup>th</sup> Tone",
							},
							{
								kind: "prokeimenon",
								text: "The Lord is King,",
								type: "1a",
								tone: "6",
								header: "First Prokeimenon of the Prophecy in the 6<sup>th</sup> Tone",
							},
							{ kind: "prokeimenon", text: "let the earth rejoice.", type: "1b" },
							{ kind: "stichos", text: "Let the many islands be glad.", type: "1" },
							{
								kind: "prokeimenon",
								text: "O sing unto the Lord a new song, for the Lord hath wrought wondrous things",
								type: "2a",
								tone: "6",
								header: "Second Prokeimenon of the Prophecy in the 6<sup>th</sup> Tone",
							},
							{ kind: "prokeimenon", text: "<p>His right hand His salvation.</p>", type: "2b" },
							{ kind: "stichos", text: "All the ends of the earth have seen the salvation of our God.", type: "2" },
						],
					},
				],
			},
		],
		hymns: [],
	},
	9818: {
		names: [{ nominative: "Wednesday of the Fifth Week of Lent", short: "Wednesday of the Fifth Week of Lent" }],
		biographies: [],
		info: [],
		refs: [],
		services: [
			{
				hymns: [],
				sections: [
					{
						section: "sexte",
						items: [
							{
								kind: "troparion",
								text: "The pains of the saints, which they suffered for Thee, O Lord, be as supplications, and all our pains do Thou heal, O Lover of mankind, we pray.",
								type: "1",
								tone: "1",
								header: "Troparion of the Prophecy in the 1<sup>st</sup> Tone",
							},
							{
								kind: "prokeimenon",
								text: "It is good to give praise unto the Lord",
								type: "1a",
								tone: "4",
								header: "First Prokeimenon of the Prophecy in the 4<sup>th</sup> Tone",
							},
							{ kind: "prokeimenon", text: "<p>and to chant unto Thy name, O Most High</p>", type: "1b" },
							{ kind: "stichos", text: "To proclaim in the morning Thy mercy, and Thy truth by night.", type: "1" },
							{
								kind: "prokeimenon",
								text: "The Lord is King,",
								type: "2a",
								tone: "6",
								header: "Second Prokeimenon of the Prophecy in the 6<sup>th</sup> Tone",
							},
							{ kind: "prokeimenon", text: "He is clothed with majesty.", type: "2b" },
							{ kind: "stichos", text: "The Lord is clothed with strength and He hath girt Himself.", type: "2" },
						],
					},
				],
			},
		],
		hymns: [],
	},
	9819: {
		names: [{ nominative: "Tuesday of the Fifth Week of Lent", short: "Tuesday of the Fifth Week of Lent" }],
		biographies: [],
		info: [],
		refs: [],
		services: [
			{
				hymns: [],
				sections: [
					{
						section: "sexte",
						items: [
							{
								kind: "troparion",
								text: "Our helper is the God of Jacob, and He is our defender in the day of affliction.",
								type: "1",
								tone: "3",
								header: "Troparion of the Prophecy in the 3<sup>rd</sup> Tone",
							},
							{
								kind: "prokeimenon",
								text: "A poor man am I,",
								type: "1a",
								tone: "6",
								header: "First Prokeimenon of the Prophecy in the 6<sup>th</sup> Tone",
							},
							{ kind: "prokeimenon", text: "and in troubles from my youth.", type: "1b" },
							{
								kind: "stichos",
								text: "O Lord God of my salvation, by day have I cried and by night before Thee.",
								type: "1",
							},
							{
								kind: "prokeimenon",
								text: "Blessed is the people that knoweth jubilation.",
								type: "2a",
								tone: "6",
								header: "Second Prokeimenon of the Prophecy in the 6<sup>th</sup> Tone",
							},
							{ kind: "prokeimenon", text: "<p>and Thy salvation do Thou give unto us.</p>", type: "2b" },
							{ kind: "stichos", text: "O Lord, in the light of Thy face shall they walk.", type: "2" },
						],
					},
				],
			},
		],
		hymns: [],
	},
	9820: {
		names: [{ nominative: "Monday of the Fifth Week of Lent", short: "Monday of the Fifth Week of Lent" }],
		biographies: [],
		info: [],
		refs: [],
		services: [
			{
				hymns: [],
				sections: [
					{
						section: "sexte",
						items: [
							{
								kind: "troparion",
								text: "For our iniquities are risen against us, arise, O Lord, help us: for Thou art our Father, for we know none other beside Thee.",
								type: "1",
								tone: "3",
								header: "Troparion of the Prophecy in the 3<sup>rd</sup> Tone",
							},
							{
								kind: "prokeimenon",
								text: "Even Thine altars, O Lord of hosts",
								type: "1a",
								tone: "4",
								header: "First Prokeimenon of the Prophecy in the 4<sup>th</sup> Tone",
							},
							{ kind: "prokeimenon", text: "<p>my King and my God.</p>", type: "1b" },
							{ kind: "stichos", text: "How beloved are Thy dwellings, O Lord of hosts.", type: "1" },
							{
								kind: "prokeimenon",
								text: "Show us, O Lord, Thy mercy",
								type: "2a",
								tone: "0",
								header: "Second Prokeimenon of the Prophecy in the 8<sup>th</sup> Tone",
							},
							{ kind: "prokeimenon", text: "<p>and Thy salvation do Thou give unto us.</p>", type: "2b" },
							{
								kind: "stichos",
								text: "Thou hast been gracious, O Lord, unto Thy land; Thou hast turned back the captivity of Jacob.",
								type: "2",
							},
						],
					},
				],
			},
		],
		hymns: [],
	},
