				hymns: [],
				sections: [
					{
						section: "sexte",
						items: [
							{
								kind: "troparion",
								text: "Heal our brokenness, for we are weak and crippled with sin, O Physician of our souls, O Lover of mankind, Who knowest the mind of man.",
								type: "1",
								tone: "4",
								header: "Troparion of the Prophecy in the 4<sup>th</sup> Tone",
							},
							{
								kind: "prokeimenon",
								text: "My prayer unto the God of my life,",
								type: "1a",
								tone: "4",
								header: "First Prokeimenon of the Prophecy in the 4<sup>th</sup> Tone",
							},
							{ kind: "prokeimenon", text: "I will say unto God: Thou art my helper.", type: "1b" },
							{
								kind: "stichos",
								text: "As the hart panteth after the fountains of water, so panteth my soul after Thee, O Lord.",
								type: "1",
							},
							{
								kind: "prokeimenon",
								text: "He is the salvation of my countenance, and my God.",
								type: "2a",
								tone: "6",
								header: "Second Prokeimenon of the Prophecy in the 6<sup>th</sup> Tone",
							},
							{ kind: "prokeimenon", text: "<p>and unto my supplication give ear.</p>", type: "2b" },
							{ kind: "stichos", text: "Judge me, O God, and give judgment to my cause.", type: "2" },
						],
					},
				],
